 ActionCoreView start_original(const StableId& kind){end_talk();common.state().actors.find("player")->location=SettlementLocation{"town","market"};interact(Talk{"sender"});TaskCommand command{kind,"letter",{"market","sender","sender"}};auto q=preview_task(common,tasks,catalog,*shared,interaction,ic,access,"player",command);require(q.ok,"original task quote: "+q.error.original.code);const auto before=state();auto id=common.next_id("action");require(id.ok,"original action ID");ActionCoreView a{id.value,kind,"player",{"player","sender"},common.tick(),q.value.duration};ActionMutation insert;insert.kind=ActionMutation::Kind::insert;insert.action=a;require(common.apply_action(insert).ok,"original Action");for(const auto& id:a.participants)common.state().actors.find(id)->action_id=a.id;require(start_task_action(common,tasks,catalog,a,command,q.value).ok,"original Task writer");task_id=tasks.actions.find(a.id)->task_id;result(before,kind,ActionStarted{a.id},common.tick());return a;}
